import type { TripRequest } from "@/lib/validation/trip";
import type { V8Ranked } from "@/lib/decision/v8-matcher";
import { createLLMRequestBudgetV16,generateJsonWithRoutingV16,type LLMRequestBudgetV16 } from "@/lib/ai/model-router-v9";

type Verify={pass?:boolean;reason?:string;reject_slugs?:string[]};
function needs(ranked:V8Ranked[]){if(ranked.length<8)return false;const top=ranked.slice(0,6);if(top.some(x=>x.breakdown.season<48||x.breakdown.routeConfidence<62))return true;if(Math.abs(ranked[5].score-ranked[6].score)<1.4)return true;if(Math.abs(ranked[0].score-ranked[1].score)<1.2)return true;return false}
export async function verifyV8(request:TripRequest,ranked:V8Ranked[],budget:LLMRequestBudgetV16=createLLMRequestBudgetV16()):Promise<{checked:boolean;passed:boolean;reason:string|null;rejectSlugs:string[];model:string|null}>{
 if(!needs(ranked))return{checked:false,passed:true,reason:null,rejectSlugs:[],model:null};
 const candidates=ranked.slice(0,10).map((x,i)=>({rank:i+1,slug:x.destination.slug,name:x.destination.nameEn,score:Math.round(x.score),intent:x.breakdown.intent,season:x.breakdown.season,effort:x.breakdown.effort,duration:x.breakdown.duration,budget:x.breakdown.budget,weather:x.breakdown.weather,traveler:x.breakdown.traveler,route:x.breakdown.routeConfidence,tags:x.destination.tags}));
 const hardLanguage=/(?:μονο|χωρις|οπωσδηποτε|\b(?:only|mono|without|must)\b)/i.test(request.tripText??""),veryWeak=ranked.slice(0,6).some(x=>x.breakdown.season<40||x.breakdown.routeConfidence<50),nearTie=Math.abs(ranked[0].score-ranked[1].score)<.65,severe=hardLanguage&&veryWeak&&nearTie;
 const system="You are a final consistency checker, not a travel planner. Numeric and supplied evidence are authoritative. Never invent flights, prices, weather, hotels, attractions or availability.";
 const prompt=`Check only whether any of ranks 1-6 is clearly dominated by ranks 7-10 for this request. Reject only obvious inconsistencies. Request=${JSON.stringify({origin:request.origin,dates:[request.startDate,request.endDate],nights:request.nights,totalBudget:request.budget,groupSize:request.groupSize,moods:request.moods,traveler:request.travelerType,energy:request.desiredEnergy,social:request.socialPreference,mustHave:request.mustHave,distance:request.distancePreference,avoid:request.avoid,freeText:request.tripText??null})}. Candidates=${JSON.stringify(candidates)}. Return JSON only: {"pass":true|false,"reason":"max 120 chars","reject_slugs":["slug"]}.`;
 const routed=await generateJsonWithRoutingV16<Verify>({context:{task:"verification",text:request.tripText,deterministicConfidence:severe?.35:veryWeak?.68:.78,hardConstraintRisk:severe,contradictorySignals:veryWeak&&nearTie},budget,system,prompt,preference:"critical",validate(value){const pass=value.pass!==false,reason=typeof value.reason==="string"?value.reason.slice(0,140):undefined,reject_slugs=Array.isArray(value.reject_slugs)?value.reject_slugs.filter((x):x is string=>typeof x==="string"&&ranked.some(item=>item.destination.slug===x)).slice(0,2):[];return{pass,reason,reject_slugs};}});
 if(!routed)return{checked:false,passed:true,reason:null,rejectSlugs:[],model:null};
 return{checked:true,passed:routed.value.pass!==false,reason:routed.value.reason??null,rejectSlugs:routed.value.reject_slugs??[],model:routed.label};
}

export type RecommendationAuditRecord={
  sessionId:string;
  status:"success"|"no-result"|"error";
  stage?:string;
  timingsMs?:Record<string,number>;
  intentSource?:string;
  hardConstraint?:string|null;
  stayRequirements?:Record<string,unknown>;
  llmBudget?:Record<string,unknown>;
  catalogSize?:number;
  preCandidates?:string[];
  researchScout?:Record<string,unknown>;
  verifier?:Record<string,unknown>;
  auditor?:Record<string,unknown>;
  council?:Record<string,unknown>;
  finalSlugs?:string[];
  errorType?:string;
};

function safeRecord(record:RecommendationAuditRecord){
 return{
  event:"travel_recommendation_audit",
  at:new Date().toISOString(),
  ...record,
  // Deliberately excludes raw free text, prompts, secrets, credentials and generated reasoning.
  // llmBudget contains counts/ceilings only — never request or response content.
 };
}

export function writeRecommendationAudit(record:RecommendationAuditRecord){
 try{console.info("[travel-audit]",JSON.stringify(safeRecord(record)))}catch{console.info("[travel-audit]",record.sessionId,record.status)}
}

export function writeRecommendationAuditError(sessionId:string,stage:string,error:unknown,timingsMs?:Record<string,number>){
 writeRecommendationAudit({sessionId,status:"error",stage,timingsMs,errorType:error instanceof Error?error.name:"unknown"});
}

import { Output, ToolLoopAgent, isStepCount, tool } from "ai";
import { z } from "zod";
import { createLLMRequestBudgetV16,routedModelsV16,type LLMRequestBudgetV16 } from "@/lib/ai/model-router-v9";
import type { V8Ranked } from "@/lib/decision/v8-matcher";
import type { TripRequest } from "@/lib/validation/trip";

type SourceEvidence={title:string;domain:string;url:string;snippet:string};
type CandidateEvidence={slug:string;name:string;sources:SourceEvidence[]};
export type ResearchScoutResult={ran:boolean;source:"agent"|"not-needed"|"no-model"|"no-evidence"|"failed";inspectedSlugs:string[];preferredSlugs:string[];rejectSlugs:string[];confidence:"HIGH"|"MEDIUM"|null;summary:string|null;evidenceDomains:string[]};
const resultSchema=z.object({preferredSlugs:z.array(z.string()).max(3),rejectSlugs:z.array(z.string()).max(4),confidence:z.enum(["HIGH","MEDIUM"]),summary:z.string().max(280)});
type WikiPayload={query?:{pages?:Array<{title?:string;extract?:string}>}};
const clean=(value:unknown,max=700)=>typeof value==="string"?value.replace(/\s+/g," ").trim().slice(0,max):"";
const slugTitle=(value:string)=>value.replace(/ /g,"_");
async function wikiEvidence(host:string,query:string):Promise<SourceEvidence|null>{try{const url=new URL(`https://${host}/w/api.php`);url.search=new URLSearchParams({action:"query",generator:"search",gsrsearch:query,gsrlimit:"1",prop:"extracts",exintro:"1",explaintext:"1",redirects:"1",format:"json",formatversion:"2",origin:"*"}).toString();const response=await fetch(url,{cache:"no-store",signal:AbortSignal.timeout(3500)});if(!response.ok)return null;const payload=await response.json() as WikiPayload,page=payload.query?.pages?.[0],title=clean(page?.title,140),snippet=clean(page?.extract,700);if(!title||!snippet)return null;return{title,domain:host,url:`https://${host}/wiki/${encodeURIComponent(slugTitle(title))}`,snippet};}catch{return null}}
async function collectEvidence(request:TripRequest,ranked:V8Ranked[]):Promise<CandidateEvidence[]>{const top=ranked.slice(0,6),rows=await Promise.all(top.map(async item=>{const destination=item.destination,primary=request.language==="en"?"en.wikipedia.org":"el.wikipedia.org",primaryQuery=request.language==="en"?`${destination.nameEn} Greece`:destination.nameEl;const[wiki,voyage]=await Promise.all([wikiEvidence(primary,primaryQuery),wikiEvidence("en.wikivoyage.org",`${destination.nameEn} Greece`)]),sources=[wiki,voyage].filter((source):source is SourceEvidence=>Boolean(source));return{slug:destination.slug,name:request.language==="en"?destination.nameEn:destination.nameEl,sources};}));return rows.filter(row=>row.sources.length>0);}
export function shouldRunResearchScout(request:TripRequest,ranked:V8Ranked[]){if(!ranked.length)return false;const free=Boolean(request.tripText&&request.tripText.trim().length>=8),considered=Boolean(request.consideredDestination),evidenceHeavy=request.moods.some(mood=>["food","culture","nature","adventure"].includes(mood)),ambiguous=ranked.length>=3&&Math.abs(ranked[0].score-ranked[2].score)<=7;return free||considered||evidenceHeavy||ambiguous;}
export function applyResearchScoutRanking(ranked:V8Ranked[],result:ResearchScoutResult){if(!result.ran)return ranked;const known=new Set(ranked.map(item=>item.destination.slug)),inspected=new Set(result.inspectedSlugs.filter(slug=>known.has(slug))),preferred=new Set(result.preferredSlugs.filter(slug=>known.has(slug)&&inspected.has(slug))),rejected=new Set(result.rejectSlugs.filter(slug=>known.has(slug)&&inspected.has(slug))),high=result.confidence==="HIGH";return ranked.map(item=>{let delta=0;if(preferred.has(item.destination.slug))delta+=high?7:4;if(rejected.has(item.destination.slug))delta-=high?8:5;return{...item,score:Math.max(0,Math.min(100,item.score+delta))};}).sort((a,b)=>b.score-a.score);}

export async function runRecommendationResearchAgent(request:TripRequest,ranked:V8Ranked[],budget:LLMRequestBudgetV16=createLLMRequestBudgetV16()):Promise<ResearchScoutResult>{
 if(!shouldRunResearchScout(request,ranked))return{ran:false,source:"not-needed",inspectedSlugs:[],preferredSlugs:[],rejectSlugs:[],confidence:null,summary:null,evidenceDomains:[]};
 const ambiguous=ranked.length>=3&&Math.abs(ranked[0].score-ranked[2].score)<=5,hardLanguage=/(?:μονο|χωρις|οπωσδηποτε|\b(?:only|mono|without|must)\b)/i.test(request.tripText??"");
 const routes=routedModelsV16({task:"research",text:request.tripText,deterministicConfidence:ambiguous?.68:.86,hardConstraintRisk:hardLanguage,contradictorySignals:ambiguous&&hardLanguage},"creative");if(!routes.length)return{ran:false,source:"no-model",inspectedSlugs:[],preferredSlugs:[],rejectSlugs:[],confidence:null,summary:null,evidenceDomains:[]};
 const started=Date.now(),budgetMs=10_000;
 for(const route of routes){const remaining=Math.min(route.timeoutMs,budgetMs-(Date.now()-started));if(remaining<1500)break;if(!budget.reserve(route,2))continue;let evidence:CandidateEvidence[]=[];const searchTravelEvidence=tool({description:"Search fresh public destination evidence for every finalist before judging fit.",inputSchema:z.object({focus:z.enum(["fit","tradeoffs","local-character"])}),execute:async()=>{evidence=await collectEvidence(request,ranked);return{request:{dates:[request.startDate,request.endDate],moods:request.moods,mustHave:request.mustHave,avoid:request.avoid,freeText:request.tripText??null},candidates:evidence};}}),candidates=ranked.slice(0,6).map(item=>({slug:item.destination.slug,name:request.language==="en"?item.destination.nameEn:item.destination.nameEl,tags:item.destination.tags})),instructions=`You are the Research Scout for a Greek travel recommender. You are not allowed to decide from memory. You MUST call searchTravelEvidence before producing an answer. Compare only supplied candidate slugs. Use only evidence returned by the tool plus supplied preferences. Never invent attractions, events, businesses, prices, routes, ratings, weather or availability. A rejectSlug requires a clear conflict visible in fetched evidence; missing evidence is not a rejection. Return preferredSlugs, rejectSlugs, confidence and a short summary.`;
  try{const agent=new ToolLoopAgent({model:route.model,maxOutputTokens:route.maxOutputTokens,instructions,tools:{searchTravelEvidence},output:Output.object({schema:resultSchema,name:"research_scout_result",description:"Grounded shortlist research verdict."}),stopWhen:isStepCount(3)}),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),remaining);try{const result=await agent.generate({prompt:`Traveler request=${JSON.stringify({origin:request.origin,dates:[request.startDate,request.endDate],nights:request.nights,budget:request.budget,groupSize:request.groupSize,moods:request.moods,travelerType:request.travelerType,mustHave:request.mustHave,avoid:request.avoid,pace:request.pace,desiredEnergy:request.desiredEnergy,socialPreference:request.socialPreference,tripText:request.tripText??null,consideredDestination:request.consideredDestination??null})}. Candidate slugs=${JSON.stringify(candidates)}. Search first, then return the grounded result.`,abortSignal:controller.signal});if(!result.output||!evidence.length)continue;const inspected=new Set(evidence.map(item=>item.slug)),preferred=result.output.preferredSlugs.filter(slug=>inspected.has(slug)&&ranked.some(item=>item.destination.slug===slug)),rejected=result.output.rejectSlugs.filter(slug=>inspected.has(slug)&&ranked.some(item=>item.destination.slug===slug)),evidenceDomains=[...new Set(evidence.flatMap(item=>item.sources.map(source=>source.domain)))];return{ran:true,source:"agent",inspectedSlugs:[...inspected],preferredSlugs:preferred,rejectSlugs:rejected,confidence:result.output.confidence,summary:result.output.summary,evidenceDomains};}finally{clearTimeout(timer)}}catch{}
 }
 return{ran:false,source:"failed",inspectedSlugs:[],preferredSlugs:[],rejectSlugs:[],confidence:null,summary:null,evidenceDomains:[]};
}

import { geographyConstraint, matchesGeographyConstraint } from "@/lib/decision/geography-constraint";
import { criterionTruthV26 } from "@/lib/decision/criterion-truth-v26";
import { diversifyV8, type V8Ranked } from "@/lib/decision/v8-matcher";
import type { TripRequest } from "@/lib/validation/trip";
import { researchIntent, satisfiesResearchNeed } from "@/lib/decision/research-intent-v13";
import type { DestinationEvidenceBundle } from "@/lib/decision/types";
import { createLLMRequestBudgetV16,generateJsonWithRoutingV16,type LLMRequestBudgetV16 } from "@/lib/ai/model-router-v9";

export type AuditIssue={slug:string;code:"HARD_CONSTRAINT"|"MUST_HAVE"|"LOW_EVIDENCE"|"RESEARCH_EVIDENCE";detail:string};
export type AuditResult={passed:boolean;confidence:"HIGH"|"MEDIUM"|"LOW";issues:AuditIssue[];attempts:number;checkedBy:"deterministic"|"deterministic+local-llm"};

function deterministicAudit(request:TripRequest,items:V8Ranked[],catalog:V8Ranked["destination"][],evidence?:Map<string,DestinationEvidenceBundle>):AuditIssue[]{
 const constraint=geographyConstraint(request,catalog),research=researchIntent(request),issues:AuditIssue[]=[];
 for(const item of items){
  if(!matchesGeographyConstraint(item.destination,constraint))issues.push({slug:item.destination.slug,code:"HARD_CONSTRAINT",detail:"Does not satisfy the explicit free-text geography constraint"});
  const truth=criterionTruthV26(request,item.destination,{effortScore:item.breakdown.effort,publicStage:true});
  for(const failure of truth.failures)issues.push({slug:item.destination.slug,code:failure.startsWith("MUST_")?"MUST_HAVE":"HARD_CONSTRAINT",detail:`V26 criterion truth rejected ${failure}`});
  if(item.breakdown.season<35||item.breakdown.routeConfidence<45)issues.push({slug:item.destination.slug,code:"LOW_EVIDENCE",detail:"Season or route evidence is below the safe floor"});
  const bundle=evidence?.get(item.destination.slug);for(const need of research.needs)if(!bundle||!satisfiesResearchNeed(bundle,need))issues.push({slug:item.destination.slug,code:"RESEARCH_EVIDENCE",detail:`Missing verified ${need} evidence for the requested dates`});
 }
 return issues;
}

async function localAudit(request:TripRequest,items:V8Ranked[],budget:LLMRequestBudgetV16):Promise<Set<string>>{
 const candidates=items.map(item=>({slug:item.destination.slug,tags:item.destination.tags,seasonProfile:item.destination.seasonProfile,evidence:item.breakdown}));
 const routed=await generateJsonWithRoutingV16<{reject_slugs:string[]}>({
  context:{task:"verification",text:request.tripText,deterministicConfidence:.90,hardConstraintRisk:true,contradictorySignals:false},budget,
  system:"You are an independent result auditor, never a recommender. Audit only against supplied constraints and evidence. Never invent facts. A model may reject an unsafe option but may never override deterministic hard-criterion truth.",
  prompt:`Find only candidates that contradict the explicit request or supplied structured evidence. Return JSON only: {"reject_slugs":[]}. Request=${JSON.stringify({freeText:request.tripText,mustHave:request.mustHave,avoid:request.avoid,distance:request.distancePreference,transport:request.transportMode,dates:[request.startDate,request.endDate]})}; Candidates=${JSON.stringify(candidates)}`,
  validate(value){const reject_slugs=Array.isArray(value.reject_slugs)?value.reject_slugs.filter((slug):slug is string=>typeof slug==="string"&&items.some(item=>item.destination.slug===slug)):[];return{reject_slugs};}
 });
 return new Set(routed?.value.reject_slugs??[]);
}

export async function auditAndRepairV10(request:TripRequest,initial:V8Ranked[],pool:V8Ranked[],limit=12,evidence?:Map<string,DestinationEvidenceBundle>,budget:LLMRequestBudgetV16=createLLMRequestBudgetV16()):Promise<{items:V8Ranked[];audit:AuditResult}>{
 const catalog=pool.map(item=>item.destination);let items=initial.slice(0,limit),lastIssues:AuditIssue[]=[],usedLLM=false;
 for(let attempt=1;attempt<=3;attempt+=1){
  const deterministic=deterministicAudit(request,items,catalog,evidence),localReject=deterministic.length?new Set<string>():await localAudit(request,items,budget);if(localReject.size)usedLLM=true;
  const localIssues=[...localReject].map(slug=>({slug,code:"LOW_EVIDENCE" as const,detail:"Independent audit rejected an evidence inconsistency"})),issues=[...deterministic,...localIssues];
  if(!issues.length)return{items,audit:{passed:true,confidence:"HIGH",issues:[],attempts:attempt,checkedBy:usedLLM?"deterministic+local-llm":"deterministic"}};
  lastIssues=issues;const rejected=new Set(issues.map(issue=>issue.slug)),survivors=pool.filter(item=>!rejected.has(item.destination.slug)&&!deterministicAudit(request,[item],catalog,evidence).length);items=diversifyV8(survivors,limit,request);if(!items.length)break;
 }
 return{items:[],audit:{passed:false,confidence:"LOW",issues:lastIssues,attempts:3,checkedBy:usedLLM?"deterministic+local-llm":"deterministic"}};
}

import { V8_DIMENSIONS,type V8Dimension,type V8SemanticIntent } from "@/lib/decision/v8-types";

const clamp=(v:number)=>Math.max(0,Math.min(1,v));
const normalize=(value:string)=>value.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-zα-ω0-9]+/gi," ").replace(/\s+/g," ").trim();
const emptyQualifiers=():V8SemanticIntent["qualifiers"]=>({avoidCrowds:0,easyAccess:0,slowRhythm:0,walkable:0,localCharacter:0});

function editDistance(a:string,b:string){
 const prev=Array.from({length:b.length+1},(_,i)=>i),cur=Array(b.length+1).fill(0);
 for(let i=1;i<=a.length;i++){cur[0]=i;for(let j=1;j<=b.length;j++)cur[j]=Math.min(cur[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));for(let j=0;j<=b.length;j++)prev[j]=cur[j];}
 return prev[b.length];
}
function fuzzyToken(tokens:string[],targets:string[],max=1){return tokens.some(token=>token.length>=5&&targets.some(target=>Math.abs(token.length-target.length)<=max&&editDistance(token,target)<=max));}
function any(text:string,patterns:RegExp[]){return patterns.some(pattern=>pattern.test(text));}
function hasSignal(s:V8SemanticIntent){return Object.values(s.positive).some(v=>(v??0)>.05)||Object.values(s.negative).some(v=>(v??0)>.05)||s.priorities.length>0||Object.values(s.qualifiers).some(v=>v>.05)}

export function deterministicSemanticIntentV19(raw:string):V8SemanticIntent{
 const text=normalize(raw),tokens=text.split(" ").filter(Boolean),positive:Partial<Record<V8Dimension,number>>={},negative:Partial<Record<V8Dimension,number>>={},qualifiers=emptyQualifiers(),priorities:V8Dimension[]=[];
 const pos=(d:V8Dimension,v:number)=>positive[d]=Math.max(positive[d]??0,v),neg=(d:V8Dimension,v:number)=>negative[d]=Math.max(negative[d]??0,v),priority=(d:V8Dimension)=>{if(!priorities.includes(d))priorities.push(d)};
 if(!text)return{positive,negative,priorities,qualifiers,confidence:1,source:"structured",rationale:[]};
 let fuzzy=false;
 const food=any(text,[/φαγητ|γαστρονομ|ταβερν|εστιατορ|food|restaurant|tavern|fagit|faght|gastronom|estiatori/])||fuzzyToken(tokens,["φαγητο","fagito"]);
