 qualifiers.avoidCrowds=any(text,[/τουριστοπαγ|πολυκοσμ|πολυ κοσμ|ορδ.{0,12}τουριστ|φασαρι|crowd|packed.{0,12}tourist|tourist trap|not chaos|no party crowds|polykosm|fasaria/])?1:0;
